<?php
require __DIR__ . '/includes/bootstrap.php';
require __DIR__ . '/includes/layout.php';
$slug = (string)($_GET['slug'] ?? '');
try { $stmt=db()->prepare('SELECT * FROM projects WHERE slug=?');$stmt->execute([$slug]);$project=$stmt->fetch(); }
catch(PDOException $e){$project=false;}
if (!$project) {http_response_code(404);page_header('Project not found');?><main id="main" class="container section"><h1>Project not found.</h1><p>This project is unavailable.</p><a class="btn btn-primary" href="<?= e(url('index.php#projects')) ?>">Back to projects</a></main><?php page_footer();exit;}
page_header($project['title'],$project['summary']);
?><main id="main"><section class="container section detail-section"><a class="back-link" href="<?= e(url('index.php#projects')) ?>">← All projects</a><div class="section-label">PROJECT CASE STUDY</div><div class="detail-heading"><div><h1 class="section-title"><?= e($project['title']) ?><span class="dot">.</span></h1><p class="detail-summary"><?= e($project['summary']) ?></p></div><span class="status-pill"><?= e(project_status($project['status'])) ?></span></div><div class="detail-cover project-art-1"><?php if ($project['image_path']): ?><img src="<?= e(url($project['image_path'])) ?>" alt="Screenshot of <?= e($project['title']) ?>"><?php else: ?><span class="detail-placeholder"><?= e($project['title']) ?></span><?php endif; ?></div><div class="detail-grid"><article><div class="section-label">ABOUT THE PROJECT</div><div class="detail-description"><?= nl2br(e($project['description'])) ?></div><div class="detail-actions"><?php if ($project['github_url']): ?><a class="btn btn-outline" href="<?= e($project['github_url']) ?>" target="_blank" rel="noopener noreferrer">View source ↗</a><?php endif; ?><?php if ($project['demo_url']): ?><a class="btn btn-primary" href="<?= e($project['demo_url']) ?>" target="_blank" rel="noopener noreferrer">Live demo ↗</a><?php endif; ?><?php if (!$project['github_url'] && !$project['demo_url']): ?><p class="muted">Source code and demo links are not available yet.</p><?php endif; ?></div></article><aside class="detail-facts"><div><span>TYPE</span><strong><?= e($project['category']) ?></strong></div><div><span>STATUS</span><strong><?= e(project_status($project['status'])) ?></strong></div><div><span>TECHNOLOGIES</span><div class="pills"><?php foreach(array_filter(array_map('trim',explode(',',$project['technologies']))) as $tech): ?><span><?= e($tech) ?></span><?php endforeach; ?></div><?php if (!$project['technologies']): ?><strong>To be confirmed</strong><?php endif; ?></div></aside></div></section></main><?php page_footer(); ?>
